async function readApps(){if(window.omnibloomHost&&typeof window.omnibloomHost.getApps==='function')return await window.omnibloomHost.getApps();const r=await fetch('mock-apps.json');if(!r.ok)throw Error('Apps unavailable');return r.json()}
function notify(message){obUI.toast(message)}
async function openApp(id){if(window.omnibloomHost&&typeof window.omnibloomHost.openApp==='function'){try{await window.omnibloomHost.openApp(id);notify('Open request sent.')}catch(e){notify('Could not open this app. Try again.')}}else notify('Preview only. App launch needs the Omni bridge.');}
function safeURL(value){try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)?u.href:null}catch(e){return null}}

const states={offline:['No connection','Check your connection and try the page again.','Try again','This preview does not change network settings.'],blocked:['Your console is protected','This page tried to reach a console service that web content cannot access.','View installed apps','A trusted app can be allowed through its verified installation card; websites cannot grant themselves access.'],certificate:['The connection is not secure','The site’s certificate could not be verified.','Try again','Check the console clock or contact the site owner; do not send passwords here.'],protected:['This download is protected','The service uses DRM, so Omnibloom cannot save this media.','Go to start','Use the service’s supported app or official offline option.'],app:['This app is not running','Open the installed app to continue.','Open it','App launch requires the trusted Bloom Core bridge.']};const state=new URLSearchParams(location.search).get('state')||'offline',data=states[state]||states.offline;['title','message','action','detail'].forEach((id,i)=>document.getElementById(id).textContent=data[i]);document.getElementById('action').onclick=()=>{if(state==='app'){if(trustedApp)openApp(trustedApp.id);else notify('Installed app context is unavailable.')}else if(state==='blocked')location.href='../status/index.html';else if(state==='protected')location.href='../start/index.html';else if(window.omnibloomHost?.retryNavigation)window.omnibloomHost.retryNavigation();else notify('Preview only. Retry needs the original navigation context.')};
let trustedApp=null;if(state==='app'){const button=document.getElementById('action');button.disabled=true;Promise.all([Promise.resolve().then(()=>window.omnibloomHost?.getContext?.()),readApps()]).then(([context,data])=>{const list=Array.isArray(data)?data:data.apps||[];trustedApp=list.find(app=>app.id===context?.appId&&app.verified!==false)||null;if(trustedApp){document.getElementById('title').textContent=trustedApp.name+' is not running';button.textContent='Open '+trustedApp.name;button.disabled=false}else document.getElementById('message').textContent='Open this page from a verified installed app.'}).catch(()=>{document.getElementById('message').textContent='App information is unavailable.'})}
